        placeImage: "\u05D4\u05E7\u05DC\u05E7 \u05DC\u05D4\u05E0\u05D7\u05EA \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4, \u05D0\u05D5 \u05D4\u05E7\u05DC\u05E7 \u05D5\u05D2\u05E8\u05D5\u05E8 \u05DC\u05D4\u05D2\u05D3\u05E8\u05EA \u05D4\u05D2\u05D5\u05D3\u05DC \u05E9\u05DC\u05D5 \u05D9\u05D3\u05E0\u05D9\u05EA",
