        collabStopOverridePrompt: "\u0648\u06D5\u0633\u062A\u0627\u0646\u062F\u0646\u06CC \u062F\u0627\u0646\u06CC\u0634\u062A\u0646\u06D5\u06A9\u06D5 \u0648\u06CE\u0646\u06D5\u06A9\u06CE\u0634\u0627\u0646\u06CC \u067E\u06CE\u0634\u0648\u0648\u062A \u062F\u06D5\u0646\u0648\u0648\u0633\u06CE\u062A\u06D5\u0648\u06D5 \u06A9\u06D5 \u0644\u06D5 \u0646\u0627\u0648\u062E\u06C6\u062F\u0627 \u0647\u06D5\u06B5\u06AF\u06CC\u0631\u0627\u0648\u06D5. \u0626\u0627\u06CC\u0627 \u062F\u06B5\u0646\u06CC\u0627\u06CC\u062A?\n\n(\u0626\u06D5\u06AF\u06D5\u0631 \u062F\u06D5\u062A\u06D5\u0648\u06CE\u062A \u0648\u06CE\u0646\u06D5\u06A9\u06CE\u0634\u0627\u0646\u06CC \u0646\u0627\u0648\u062E\u06C6\u06CC\u06CC \u062E\u06C6\u062A \u0628\u0647\u06CE\u06B5\u06CC\u062A\u06D5\u0648\u06D5\u060C \u0644\u06D5\u0628\u0631\u06CC \u0626\u06D5\u0648\u06D5 \u062A\u06D5\u0646\u0647\u0627 \u062A\u0627\u0628\u06CC \u0648\u06CE\u0628\u06AF\u06D5\u0695\u06D5\u06A9\u06D5 \u062F\u0627\u0628\u062E\u06D5).",
        errorAddingToLibrary: "\u0646\u06D5\u06CC\u062A\u0648\u0627\u0646\u06CC \u0628\u0695\u06AF\u06D5 \u0632\u06CC\u0627\u062F \u0628\u06A9\u0627\u062A \u0628\u06C6 \u06A9\u062A\u06CE\u0628\u062E\u0627\u0646\u06D5",
